const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',cards:'<rect x="6" y="5" width="14" height="16" rx="2"/><path d="M16 2H4a2 2 0 0 0-2 2v13"/>',quiz:'<path d="m9 11 3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>',plus:'<path d="M12 5v14M5 12h14"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v4a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-4"/>',file:'<path d="M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9zM14 2v7h7M7 14h10M7 18h6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',shuffle:'<path d="m18 3 3 3-3 3M3 18c6 0 9-12 18-12M3 6c3 0 5 2 7 6s5 6 11 6m-3-3 3 3-3 3"/>'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${icons[n]||icons.cards}</svg>`;
let db,decks=[],activeId=null,view='import',search='',filter='all',busy=false,session=null,importNotice='',pdfLib,updateTargetId=null,pendingUpdate=null,quizFormat='typed';
const deck=()=>decks.find(d=>d.id===activeId);
const uid=()=>crypto.randomUUID();
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
async function initDB(){db=await new Promise((resolve,reject)=>{const req=indexedDB.open('facefolio',1);req.onupgradeneeded=()=>req.result.createObjectStore('decks',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});decks=await new Promise((resolve,reject)=>{const r=db.transaction('decks').objectStore('decks').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});decks.sort((a,b)=>b.created-a.created);activeId=decks[0]?.id;if(activeId)view='roster';render()}
async function persist(d){if(!db){toast('Browser storage unavailable. Export a backup before closing.');return false}try{await new Promise((resolve,reject)=>{const tx=db.transaction('decks','readwrite');tx.objectStore('decks').put(d);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});return true}catch{toast('Storage is full. Export your deck to keep a backup.');return false}}
function photo(c,cls=''){return c.photo?`<img class="person-photo ${cls}" src="${esc(c.photo)}" alt="Roster portrait" loading="lazy">`:`<div class="person-photo initials ${cls}" aria-label="No photo">?</div>`}
function render(){const d=deck();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><button class="brand" data-action="home" aria-label="Facefolio home"><span class="brand-mark">f<span style="display:none">.</span></span>facefolio<small>·</small></button><div class="sidebar-label">Your learning space</div><nav><button class="nav ${view==='roster'?'active':''}" data-view="roster">${icon('grid')} My rosters ${decks.length?`<span class="count">${decks.length}</span>`:''}</button><button class="nav ${view==='study'?'active':''}" data-view="study">${icon('cards')} Flashcards</button><button class="nav ${view==='quiz'?'active':''}" data-view="quiz">${icon('quiz')} Quick quiz</button><button class="nav ${view==='import'?'active':''}" data-view="import">${icon('plus')} Import a roster</button></nav>${decks.length?`<select class="deck-select" id="deck-select" ${busy?'disabled':''} aria-label="Current roster">${decks.map(x=>`<option value="${x.id}" ${x.id===activeId?'selected':''}>${esc(x.title)}</option>`).join('')}</select>`:''}<div class="side-note"><strong>A little more familiar.</strong>Small moments of practice.<br>A room full of familiar faces.</div><div class="side-footer"><div class="avatar">${icon('lock')}</div><span>Your private workspace</span></div></aside><div class="workspace"><header class="topbar"><div>Workspace <span style="margin:0 13px;color:#b8bcb0">/</span> <b>${({import:'Import a roster',roster:'My rosters',study:'Flashcards',quiz:'Quick quiz'})[view]}</b></div><div class="local-tag"><span class="dot"></span> Stored on this device</div></header><main class="main">${view==='import'?importPage():view==='roster'?rosterPage(d):studyPage(d)}</main></div></div>`;bind();}
function importPage(){const updating=decks.find(d=>d.id===updateTargetId);return `${decks.length?`<button class="btn back-to-roster" data-action="back-to-roster" ${busy?'disabled':''}>← Back to roster</button>`:''}<div class="intro"><div><div class="eyebrow">Names are just the beginning</div><h1>${updating?'Keep your roster up to date.':'Your roster, ready to review.'}</h1><p>${updating?`Upload the latest PDF for ${esc(updating.title)}.<br>Preview who’s new and who’s gone before applying changes.`:'Upload a PDF to see everyone’s photo, name, and details.<br>Review your roster, then practice with flashcards or a quiz.'}</p></div><span class="pill">${icon('lock')} Private by design</span></div><div class="import-layout"><section class="panel"><div class="section-kicker"><span class="step">1</span> START WITH YOUR ROSTER</div><h2>${updating?'New PDF. Same roster.':'Just upload your photo roster.'}</h2><p>${updating?'Matched people keep your notes, edits, and progress.':'We’ll pair photos with names and open your roster automatically.'}</p>${decks.length?`<label class="upload-target-label" for="upload-target">Upload destination</label><select class="input upload-target" id="upload-target" ${busy?'disabled':''}><option value="">Create a new roster</option>${decks.map(d=>`<option value="${d.id}" ${d.id===updateTargetId?'selected':''}>Update ${esc(d.title)}</option>`).join('')}</select>`:''}<div class="dropzone" id="dropzone" tabindex="0" role="button" aria-label="Choose a PDF roster">${busy?'<div class="spinner"></div><strong id="import-progress">Reading your roster…</strong><p>This stays on your device.</p>':`<div class="file-icon">${icon('file')}</div><strong>${updating?'Drop the updated PDF here':'Drop your photo roster here'}</strong><p>PDF files · up to 25 MB</p><button class="btn primary" data-action="choose-pdf">${icon('upload')} ${updating?'Choose updated PDF':'Choose a PDF'}</button>`}</div><div class="privacy">${icon('lock')}<span>Your PDF is processed in your browser. Photos and<br>details stay on this device.</span></div><p style="font-size:10px;margin:16px 0 0">Works best with selectable text and a photo grid.<br>Scanned PDFs need text recognition before import.</p></section><section class="panel preview-panel"><div class="preview-label"><div class="section-kicker"><span class="step">2</span> MEET YOUR FLASHCARDS</div><span class="mini-label">Example</span></div><div class="preview-stack"><span class="sparkle">✧</span><div class="sample-card"><div class="portrait-art" role="img" aria-label="Illustrated example person"><div class="body"></div><div class="neck"></div><div class="head"></div></div><h3>Alex Morgan</h3><p>Environmental Studies</p><div class="sample-meta"><span>Junior</span><span>they / them</span></div></div></div><div class="preview-caption">A face, a name, a little more connection.</div></section></div><section class="how"><div class="how-heading"><span>FROM ROSTER TO RECOGNITION</span></div><div class="steps"><div class="step-item"><span class="step-num">01</span><div><h3>Upload your PDF</h3><p>Bring a class, team, or community<br>photo roster. We’ll handle the cards.</p></div></div><div class="step-item"><span class="step-num">02</span><div><h3>Review your people</h3><p>Review the cards. Edit a detail,<br>add a major, or leave yourself a note.</p></div></div><div class="step-item"><span class="step-num">03</span><div><h3>Keep it current</h3><p>Roster changed? Upload a new PDF.<br>Your notes and progress come with you.</p></div></div></div></section><div class="footer-note">Already have a deck? <button class="text-btn" data-action="restore">Restore a Facefolio backup</button></div>`}
function rosterPage(d){if(!d)return `<div class="empty"><h1>Your people belong here.</h1><p>Import your first photo roster to get started.</p><button class="btn primary" data-view="import">Import a roster ${icon('arrow')}</button></div>`;const known=d.cards.filter(c=>c.known).length;const cards=d.cards.filter(c=>(filter==='all'||(filter==='learning'?!c.known:c.known))&&[c.name,c.program,c.major,c.year,c.pronouns,c.notes].join(' ').toLowerCase().includes(search.toLowerCase()));return `<div class="intro"><div><div class="eyebrow">Your people, at a glance</div><h1>${esc(d.title)}</h1><p>${esc(d.fileName||'Your personal roster')} · ${d.cards.length} people${d.updatedAt?` · Updated ${new Date(d.updatedAt).toLocaleDateString()}`:''}</p></div><div class="intro-actions"><button class="btn" data-action="update-roster">${icon('upload')} Update roster</button><button class="btn primary" data-view="study">Start studying ${icon('arrow')}</button></div></div>${d.previousVersion?`<div class="update-history"><span>Latest PDF: ${esc(d.fileName)} · You can restore the roster before this update.</span><button class="text-btn" data-action="undo-update">Undo last update</button></div>`:''}${importNotice?`<div class="notice review-banner"><div>${esc(importNotice)}</div><button class="text-btn" data-action="dismiss-notice">Got it</button></div>`:''}<div class="stats"><div class="stat"><b>${d.cards.length}</b>People in this roster</div><div class="stat"><b>${d.cards.length-known}</b>Still getting familiar</div><div class="stat"><b>${known}</b>Names you know</div></div><div class="toolbar"><input id="search" class="input search" placeholder="Search names, programs, or details…" aria-label="Search people" value="${esc(search)}"><select id="filter" class="input" aria-label="Filter by learning progress"><option value="all" ${filter==='all'?'selected':''}>Everyone</option><option value="learning" ${filter==='learning'?'selected':''}>Still learning</option><option value="known" ${filter==='known'?'selected':''}>Know it</option></select><button class="btn" data-action="add">${icon('plus')} Add person</button><button class="btn" data-action="export">Export backup</button><button class="btn" data-action="deck-settings" aria-label="Roster settings">•••</button></div><div class="cards">${cards.map(c=>`<article class="person-card">${c.known?'<span class="mastered-mark">✓ Known</span>':''}${photo(c)}<h3>${esc(c.name)}</h3><p>${esc(c.major||c.program||'No program listed')}</p><p>${esc(c.year||'—')}</p><div class="card-actions"><button class="btn" data-edit="${c.id}">Edit details</button><button class="btn" data-toggle-known="${c.id}" aria-label="${c.known?'Mark still learning':'Mark known'}">${c.known?'↺':'✓'}</button></div></article>`).join('')}</div>${!cards.length?'<div class="empty">No people match this view.</div>':''}<div class="footer-note">Review photo–name matches after every import. You can edit every card.</div>`}
function startSession(mode=view,onlyLearning=false){const d=deck();if(!d?.cards.length){view='import';render();return}const cards=d.cards.filter(c=>!onlyLearning||!c.known);session={mode,ids:cards.map(c=>c.id),index:0,flipped:false,answered:null,correct:0,review:0,onlyLearning};view=mode;nextOptions();render();focusQuiz()}
function nextOptions(){if(!session||session.mode!=='quiz')return;const c=deck().cards.find(c=>c.id===session.ids[session.index]);if(!c)return;const others=shuffle(deck().cards.filter(x=>x.id!==c.id&&x.name!==c.name));const unique=others.filter((x,i,a)=>a.findIndex(q=>q.name===x.name)===i);session.options=shuffle([c,...unique.slice(0,3)]).map(x=>x.id)}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function studyPage(d){if(!d?.cards.length)return `<div class="empty"><h1>Start with a roster.</h1><p>Your first flashcards are one PDF away.</p><button class="btn primary" data-view="import">Choose a PDF</button></div>`;if(!session||session.mode!==view){session={mode:view,ids:d.cards.map(c=>c.id),index:0,flipped:false,answered:null,correct:0,review:0,onlyLearning:false};nextOptions()}
const s=session,c=d.cards.find(c=>c.id===s.ids[s.index]),done=s.index>=s.ids.length;return `<div class="intro"><div><div class="eyebrow">${esc(d.title)}</div><h1>${view==='quiz'?'Put a name to the face.':'A little more familiar.'}</h1><p>${view==='quiz'?(quizFormat==='typed'?'See the person. Type their name.':'See the person. Choose their name.'):'Think of their name. Flip to make the connection.'}</p></div></div><div class="study-wrap">${view==='quiz'?`<div class="quiz-format mode-group" role="group" aria-label="Quiz answer mode"><button data-action="quiz-typed" class="${quizFormat==='typed'?'selected':''}" aria-pressed="${quizFormat==='typed'}">Type the name</button><button data-action="quiz-choice" class="${quizFormat==='choice'?'selected':''}" aria-pressed="${quizFormat==='choice'}">Multiple choice</button></div>`:''}<div class="study-top"><div class="mode-group"><button class="${!s.onlyLearning?'selected':''}" data-action="practice-all">Everyone</button><button class="${s.onlyLearning?'selected':''}" data-action="practice-learning">Still learning</button></div><button class="btn" data-action="shuffle">${icon('shuffle')} Shuffle</button></div>${done?`<section class="panel completion"><div class="eyebrow">${s.ids.length?'A little practice goes a long way':'All caught up'}</div><h2>${s.ids.length?'Nice to meet them. Again.':'A room full of familiar faces.'}</h2><div class="big-stat">${view==='quiz'?`${s.correct}/${s.ids.length}`:s.ids.length}</div><p>${view==='quiz'?'Names matched correctly.':`Cards practiced · ${s.correct} marked “know it”.`}<br>${s.review?'A few more faces to get familiar with.':'Keep the connection fresh with another round.'}</p><div class="study-actions"><button class="btn" data-view="roster">Back to roster</button><button class="btn primary" data-action="practice-all">Practice again</button></div></section>`:`<div class="study-top" style="margin-top:24px"><span>${view==='quiz'?'Question':'Card'} ${s.index+1} of ${s.ids.length}</span><span>${Math.round(s.index/s.ids.length*100)}% through this round</span></div><div class="progress"><div style="width:${s.index/s.ids.length*100}%"></div></div>${view==='study'?`<button class="flashcard" data-action="flip" aria-label="${s.flipped?'Show photo':'Reveal name and details'}">${photo(c,s.flipped?'back-photo':'')}${s.flipped?`<h2>${esc(c.name)}</h2>${[c.major,c.program,c.year,c.pronouns,c.notes].filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('')}<span class="hint">Tap to see the face</span>`:'<p style="margin-top:24px">Who’s this?</p><span class="hint">Click to reveal · space to flip</span>'}</button><div class="study-actions"><button class="btn" data-action="previous" ${s.index===0?'disabled':''} aria-label="Previous card">←</button><button class="btn" data-action="learning" ${!s.flipped?'disabled':''}>↺ Still learning</button><button class="btn primary" data-action="known" ${!s.flipped?'disabled':''}>${icon('check')} Know it</button><button class="btn" data-action="skip" aria-label="Skip card">→</button></div><div class="keyboard-hint"><span class="kbd">Space</span> flip <span style="margin:0 9px">·</span><span class="kbd">1</span> still learning <span style="margin:0 9px">·</span><span class="kbd">2</span> know it</div>`:`<div class="flashcard" style="min-height:270px">${photo(c)}<p style="margin-top:20px">What’s their name?</p></div>${quizFormat==='typed'?`<form id="typed-answer-form" class="typed-answer-form"><label for="typed-answer">Their name</label><div class="typed-answer-row"><input id="typed-answer" class="input" name="answer" placeholder="Type a name…" autocomplete="off" autocorrect="off" autocapitalize="words" spellcheck="false" maxlength="200" aria-describedby="typed-hint" ${s.answered?'disabled':''} value="${esc(s.typedAnswer||'')}"><button class="btn primary" type="submit" ${s.answered?'disabled':''}>Check answer</button></div><p id="typed-hint" class="subtle">First and last name are enough unless someone shares them. Full names work too. Case, accents, and punctuation don’t matter.</p>${!s.answered?'<button class="text-btn" type="button" data-action="reveal-answer">I don’t know — show the name</button>':''}</form>`:s.options.length<2?'<div class="notice" style="margin-top:18px">Add another person to make a multiple-choice quiz.</div>':`<div class="quiz-options">${s.options.map((id,i)=>{const o=d.cards.find(x=>x.id===id);return `<button class="quiz-option ${s.answered?(id===c.id?'correct':id===s.answered?'incorrect':''):''}" data-answer="${id}" ${s.answered?'disabled':''}><span style="color:#a0a890;margin-right:12px">${i+1}</span>${esc(o.name)}</button>`}).join('')}</div>`}${s.answered?`<div class="quiz-result" role="status">${s.answered===c.id?'That’s right. Another familiar face.':`This is ${esc(c.name)}. You’ll see them again in “Still learning”.`}</div><div class="study-actions"><button class="btn primary" data-action="next-question">${s.index===s.ids.length-1?'See results':'Next person'} ${icon('arrow')}</button></div>`:''}`}`}</div>`}
async function importPDF(file,targetId=updateTargetId,forceNew=false){if(busy||!file)return;const target=decks.find(d=>d.id===targetId);if(!target&&!forceNew){const matches=decks.filter(d=>d.fileName?.toLowerCase()===file.name.toLowerCase());if(matches.length){chooseUploadDestination(file,matches);return}}if(file.size>25*1024*1024){toast('Please choose a PDF smaller than 25 MB.');return}if(!/\.pdf$/i.test(file.name)&&file.type!=='application/pdf'){toast('Please choose a PDF file.');return}updateTargetId=target?.id||null;busy=true;importNotice='';view='import';render();let pdf,loadingTask;
try{pdfLib??=await import('./vendor/pdf.mjs');pdfLib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;const data=new Uint8Array(await file.arrayBuffer());loadingTask=pdfLib.getDocument({data,isEvalSupported:false});pdf=await loadingTask.promise;if(pdf.numPages>80)throw Error('Please split this roster into PDFs of 80 pages or fewer.');let cards=[],skipped=0,hasText=false,title=file.name.replace(/\.pdf$/i,'').replace(/[_-]/g,' '),expected=null;
for(let n=1;n<=pdf.numPages;n++){$('#import-progress').textContent=`Finding familiar faces · page ${n} of ${pdf.numPages}`;const page=await pdf.getPage(n),vp=page.getViewport({scale:1}),content=await page.getTextContent(),ops=await page.getOperatorList();const text=content.items.filter(i=>i.str).map(i=>{const t=pdfLib.Util.transform(vp.transform,i.transform);return {text:i.str,x:t[4],cx:t[4]+i.width/2,y:t[5],h:i.height}});if(text.some(t=>t.text.trim()))hasText=true;
if(n===1){const all=text.map(t=>t.text).join(' ');const course=all.match(/Course:\s*(.+?)\s*(?:\(|Current|Section)/i);if(course)title=course[1].trim();const en=all.match(/Current Enrollment:\s*(\d+)/i);if(en)expected=Number(en[1]);}
const boxes=imageBoxes(ops,pdfLib.OPS,vp,pdfLib.Util.transform),found=matchCards(boxes,text,vp.width,vp.height);if(!found.length){skipped++;continue}const scale=Math.min(3,2100/Math.max(vp.width,vp.height)),rvp=page.getViewport({scale}),canvas=document.createElement('canvas');canvas.width=Math.ceil(rvp.width);canvas.height=Math.ceil(rvp.height);await page.render({canvasContext:canvas.getContext('2d'),viewport:rvp}).promise;
for(const c of found){const crop=document.createElement('canvas');crop.width=216;crop.height=Math.round(216*c.box.h/c.box.w);const ctx=crop.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,crop.width,crop.height);ctx.drawImage(canvas,c.box.x*scale,c.box.y*scale,c.box.w*scale,c.box.h*scale,0,0,crop.width,crop.height);cards.push({...c,id:uid(),photo:crop.toDataURL('image/jpeg',.88),known:false,page:n});delete cards.at(-1).box;}canvas.width=0;canvas.height=0;page.cleanup();}
if(!cards.length)throw Error(hasText?'No photo-and-name pairs found. Use a roster with individual photos and selectable names directly below each photo.':'This PDF appears to be scanned. Run text recognition (OCR) in a PDF editor, then import it again.');const importReport={expected,skipped,count:cards.length};
if(target){pendingUpdate=planRosterUpdate(target,cards,file.name,importReport);activeId=target.id;view='roster';}
else{const d={id:uid(),title,fileName:file.name,created:Date.now(),cards:cards.map(importedCard),importReport};decks.unshift(d);activeId=d.id;const saved=await persist(d);session=null;search='';filter='all';view='roster';importNotice=`Your roster is ready: ${cards.length} people. Review the photo–name matches, then start studying.${reportWarning(importReport)}${!saved?' Export a backup now: this deck could not be saved on this device.':''}`;updateTargetId=null;}}
catch(e){toast(e.name==='PasswordException'?'This PDF is password-protected. Import an unlocked copy.':e.message||'Could not read this PDF. Try another file.');$('#import-progress')?.insertAdjacentHTML('afterend',`<p class="error">${esc(e.message)}</p>`);importNotice=e.message;}
finally{try{await loadingTask?.destroy()}catch{}busy=false;render();if(view==='import'&&importNotice){$('#dropzone').insertAdjacentHTML('afterend',`<p class="error" role="alert">${esc(importNotice)}</p>`);importNotice=''}$('#pdf-input').value='';if(pendingUpdate)showUpdateReview();window.scrollTo({top:0});}}
function reportWarning(report){return `${report?.skipped?` ${report.skipped} page(s) had no supported photo grid.`:''}${report?.expected&&report.expected!==report.count?` The PDF lists ${report.expected} people, but ${report.count} were extracted. Check for missing or extra people.`:''}`}
function chooseUploadDestination(file,matches){const dialog=$('#editor');dialog.innerHTML=`<div class="modal-head"><h2>Update an existing roster?</h2><button class="close" aria-label="Close dialog">×</button></div><p class="subtle">You’ve uploaded a PDF with this filename before. Update its roster to keep your notes and progress, or make a separate roster.</p><label class="upload-target-label" for="existing-roster">Existing roster</label><select class="input upload-target" id="existing-roster">${matches.map(d=>`<option value="${d.id}">${esc(d.title)} · ${d.cards.length} people</option>`).join('')}</select><div class="modal-actions"><button class="btn" id="new-upload">Create new roster</button><button class="btn primary" id="existing-upload">Update selected roster</button></div>`;dialog.querySelector('.close').onclick=()=>{dialog.close();$('#pdf-input').value=''};$('#new-upload').onclick=()=>{dialog.close();importPDF(file,null,true)};$('#existing-upload').onclick=()=>{const id=$('#existing-roster').value;dialog.close();importPDF(file,id,true)};dialog.showModal()}
function showUpdateReview(){const {next,summary}=pendingUpdate,dialog=$('#editor');const list=(title,names)=>names.length?`<details class="change-list"><summary>${title} (${names.length})</summary><ul>${names.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></details>`:'';dialog.innerHTML=`<div class="modal-head"><h2>Review your roster update.</h2><button class="close" aria-label="Cancel update">×</button></div><p class="subtle">${esc(next.title)} · ${esc(next.fileName)}</p><div class="update-counts"><div><b>${summary.retained.length}</b>Matched</div><div><b>${summary.added.length}</b>Added</div><div><b>${summary.removed.length}</b>Removed</div></div><p class="update-explanation">Matched people keep your notes, edits, and learning progress. Photos and unedited details refresh from the PDF. Removed people leave this roster; you can undo the last update.</p>${reportWarning(next.importReport)?`<div class="notice warn">${esc(reportWarning(next.importReport))}</div>`:''}${summary.ambiguous.length?`<div class="notice warn">Some names occur more than once. We have not transferred notes or progress for those names. Review their cards after updating.</div>`:''}${list('New people',summary.added)}${list('People no longer in this PDF',summary.removed)}${list('Names needing review',summary.ambiguous)}${list('Matched people',summary.retained)}<p class="subtle">Matches use the original full name. Changed names appear as an addition and a removal.</p><p id="update-save-error" class="error" role="alert"></p><div class="modal-actions"><button class="btn" id="cancel-update">Keep current roster</button><button class="btn primary" id="apply-update">Apply roster update</button></div>`;
const cancel=()=>{pendingUpdate=null;updateTargetId=null;dialog.oncancel=null;dialog.close();render()};dialog.querySelector('.close').onclick=cancel;$('#cancel-update').onclick=cancel;dialog.oncancel=e=>{e.preventDefault();cancel()};$('#apply-update').onclick=async()=>{const button=$('#apply-update');button.disabled=true;button.textContent='Saving…';if(!await persist(next)){button.disabled=false;button.textContent='Try saving again';$('#update-save-error').textContent='The update was not saved. Your current roster is unchanged. Free browser storage and try again.';return}decks=decks.map(d=>d.id===next.id?next:d);activeId=next.id;session=null;search='';filter='all';view='roster';pendingUpdate=null;updateTargetId=null;importNotice=`Roster updated: ${summary.added.length} added, ${summary.removed.length} removed, ${summary.retained.length} matched.${reportWarning(next.importReport)}`;dialog.oncancel=null;dialog.close();render();window.scrollTo({top:0});toast('Your roster is up to date.')};dialog.showModal()}
async function undoUpdate(){const current=deck();if(!current?.previousVersion)return;const restored={...current.previousVersion,title:current.title};if(!await persist(restored))return;decks=decks.map(d=>d.id===current.id?restored:d);session=null;search='';filter='all';importNotice='Previous roster restored, including its photos, notes, and learning progress.';render();toast('Last roster update undone.')}
function bind(){if($('#typed-answer-form'))$('#typed-answer-form').onsubmit=e=>{e.preventDefault();submitTypedAnswer()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>{e.stopPropagation();action(b.dataset.action)});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editCard(b.dataset.edit));document.querySelectorAll('[data-toggle-known]').forEach(b=>b.onclick=async()=>{const c=deck().cards.find(c=>c.id===b.dataset.toggleKnown);c.known=!c.known;await persist(deck());render()});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(b.dataset.answer));if($('#search'))$('#search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;render()};if($('#upload-target'))$('#upload-target').onchange=e=>{updateTargetId=e.target.value||null;render()};if($('#deck-select'))$('#deck-select').onchange=e=>{activeId=e.target.value;session=null;search='';filter='all';importNotice='';render()};const zone=$('#dropzone');if(zone&&!busy){zone.onclick=()=>$('#pdf-input').click();zone.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#pdf-input').click()}};zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag')};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');importPDF(e.dataTransfer.files[0])}}}
function navigate(v){if(busy){toast('Your roster is still being imported.');return}if((v==='study'||v==='quiz')&&v!==view)session=null;if(v==='import')updateTargetId=null;view=v;render();window.scrollTo({top:0});focusQuiz()}
async function action(a){if(busy&&a!=='choose-pdf')return;const d=deck(),s=session;switch(a){case'back-to-roster':if(updateTargetId)activeId=updateTargetId;updateTargetId=null;importNotice='';navigate('roster');break;case'quiz-typed':case'quiz-choice':quizFormat=a==='quiz-typed'?'typed':'choice';session.typedAnswer='';render();focusQuiz();break;case'reveal-answer':await submitTypedAnswer(true);break;case'update-roster':navigate('import');updateTargetId=d.id;render();break;case'undo-update':await undoUpdate();break;case'home':navigate(decks.length?'roster':'import');break;case'choose-pdf':if(!busy)$('#pdf-input').click();break;case'restore':$('#json-input').click();break;case'dismiss-notice':importNotice='';render();break;case'add':editCard();break;case'export':exportDeck();break;case'deck-settings':deckSettings();break;case'flip':s.flipped=!s.flipped;render();break;case'practice-all':startSession(view,false);break;case'practice-learning':startSession(view,true);break;case'shuffle':s.ids=shuffle(s.ids);s.index=0;s.flipped=false;s.answered=null;s.typedAnswer='';s.correct=0;s.review=0;s.ratings={};nextOptions();render();break;case'previous':if(s.index>0){s.index--;s.flipped=false;render()}break;case'known':case'learning':if(!s.flipped)return;d.cards.find(c=>c.id===s.ids[s.index]).known=a==='known';s.ratings??={};s.ratings[s.ids[s.index]]=a==='known';s.correct=Object.values(s.ratings).filter(Boolean).length;s.review=Object.values(s.ratings).filter(v=>!v).length;await persist(d);advance();break;case'skip':case'next-question':advance();break;}}
function advance(){session.index++;session.flipped=false;session.answered=null;session.typedAnswer='';nextOptions();render();focusQuiz()}
function focusQuiz(){if(view==='quiz'&&quizFormat==='typed'&&!session?.answered)$('#typed-answer')?.focus()}
async function submitTypedAnswer(reveal=false){if(session?.answered)return;const input=$('#typed-answer'),value=input?.value||'';if(!reveal&&!value.trim()){input.setCustomValidity('Enter a name, or choose “I don’t know”.');input.reportValidity();input.oninput=()=>input.setCustomValidity('');return}session.typedAnswer=reveal?'':value;const c=deck().cards.find(c=>c.id===session.ids[session.index]);await answer(!reveal&&checkTypedName(value,c,deck().cards)?c.id:'incorrect')}
async function answer(id){const current=session,d=deck();if(!current||current.answered)return;const c=d.cards.find(c=>c.id===current.ids[current.index]);current.answered=id;c.known=id===c.id;if(c.known)current.correct++;else current.review++;render();$('#typed-answer-form')?.querySelector('input')?.blur();document.querySelector('[data-action="next-question"]')?.focus();await persist(d)}
function editCard(id){const c=deck().cards.find(c=>c.id===id)||{id:uid(),name:'',major:'',program:'',year:'',pronouns:'',notes:'',known:false};const dialog=$('#editor');dialog.innerHTML=`<form id="edit-form"><div class="modal-head"><h2>${id?'A little more about them.':'Meet someone new.'}</h2><button type="button" class="close" aria-label="Close dialog">×</button></div><div class="edit-photo">${photo(c)}<div><input type="file" id="photo-file" accept="image/png,image/jpeg,image/webp" style="font-size:11px;max-width:240px" aria-label="Replace photo"><p>Change the photo if the import needs a correction.</p></div></div><div class="form-grid">${[['name','Full name','wide'],['major','Major / concentration',''],['program','School / degree / program',''],['year','Class year',''],['pronouns','Pronouns','']].map(([key,label,cl])=>`<label class="${cl}">${label}<input class="input" name="${key}" value="${esc(c[key])}" ${key==='name'?'required maxlength="200"':'maxlength="300"'}></label>`).join('')}<label class="wide">Notes<textarea class="input" name="notes" rows="3" maxlength="2000" placeholder="A detail to help the name stick…">${esc(c.notes)}</textarea></label></div>${c.source?`<details class="source"><summary>Original PDF text · page ${c.page}</summary>${esc(c.source)}</details>`:''}<div class="modal-actions">${id?'<button class="btn danger" type="button" id="delete-card">Delete card</button>':''}<button class="btn primary" type="submit">Save details</button></div></form>`;dialog.querySelector('.close').onclick=()=>dialog.close();let newPhoto=c.photo;$('#photo-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024){toast('Choose a photo under 10 MB.');return}try{const bmp=await createImageBitmap(file),can=document.createElement('canvas');can.width=300;can.height=Math.min(600,Math.round(300*bmp.height/bmp.width));can.getContext('2d').drawImage(bmp,0,0,can.width,can.height);newPhoto=can.toDataURL('image/jpeg',.88);bmp.close();const current=dialog.querySelector('.person-photo');current.outerHTML=`<img class="person-photo" src="${newPhoto}" alt="Updated portrait">`}catch{toast('That image could not be read. Try JPG or PNG.')}};$('#edit-form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(!values.name.trim()){toast('Please enter a name.');return}c.importedName??=c.name;c.importedFields??=Object.fromEntries(editableFields.map(k=>[k,c[k]||'']));c.overrides??={};for(const field of editableFields){const next=field==='photo'?newPhoto:values[field]?.trim();if(next!==undefined&&next!==(c[field]||''))c.overrides[field]=true}Object.assign(c,Object.fromEntries(Object.entries(values).map(([k,v])=>[k,v.trim()])),{photo:newPhoto});if(!id)deck().cards.push(c);await persist(deck());session=null;dialog.close();render();toast('Details saved')};if(id)$('#delete-card').onclick=async()=>{if(!confirm(`Delete ${c.name} from this roster?`))return;deck().cards=deck().cards.filter(x=>x.id!==id);await persist(deck());session=null;dialog.close();render()};dialog.showModal()}
function deckSettings(){const d=deck(),dialog=$('#editor');dialog.innerHTML=`<form id="settings"><div class="modal-head"><h2>Make this roster yours.</h2><button type="button" class="close" aria-label="Close dialog">×</button></div><label class="subtle">Roster title<input class="input" style="display:block;width:100%;margin-top:8px" name="title" value="${esc(d.title)}" required maxlength="150"></label><div class="modal-actions"><button type="button" class="btn danger" id="delete-deck">Delete roster</button><button type="button" class="btn" id="reset-progress">Reset progress</button><button class="btn primary">Save title</button></div><p class="subtle" style="line-height:1.7;margin-top:20px">Decks are saved in this browser on this device. Export a backup before clearing browser data or moving to another device.</p></form>`;dialog.querySelector('.close').onclick=()=>dialog.close();$('#settings').onsubmit=async e=>{e.preventDefault();const title=new FormData(e.target).get('title').trim();if(!title)return;d.title=title;await persist(d);dialog.close();render()};$('#reset-progress').onclick=async()=>{if(!confirm('Reset learning progress for every person in this roster?'))return;d.cards.forEach(c=>c.known=false);await persist(d);session=null;dialog.close();render();toast('A fresh start. Progress reset.')};$('#delete-deck').onclick=async()=>{if(!confirm(`Delete “${d.title}” and its photos from this device?`))return;if(db)await new Promise((resolve,reject)=>{const tx=db.transaction('decks','readwrite');tx.objectStore('decks').delete(d.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});decks=decks.filter(x=>x.id!==d.id);activeId=decks[0]?.id;session=null;view=decks.length?'roster':'import';dialog.close();render()};dialog.showModal()}
function exportDeck(){const blob=new Blob([JSON.stringify({format:'facefolio',version:1,deck:deck()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=deck().title.replace(/[^a-z0-9_-]/gi,'-')+'.facefolio.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported with photos and progress.')}
async function restore(file){if(!file)return;try{if(file.size>60*1024*1024)throw Error('Backup must be smaller than 60 MB.');const data=JSON.parse(await file.text());if(data.format!=='facefolio'||data.version!==1||!Array.isArray(data.deck?.cards)||data.deck.cards.length>5000)throw Error('Choose a valid Facefolio backup.');const original=data.deck;const d={id:uid(),title:String(original.title||'Restored roster').slice(0,150),fileName:String(original.fileName||''),created:Date.now(),cards:original.cards.map(c=>{if(typeof c.name!=='string'||!c.name.trim())throw Error('This backup contains an invalid card.');const result={id:uid(),known:c.known===true};for(const k of ['name','major','program','year','pronouns','notes','source'])result[k]=String(c[k]||'').slice(0,4000);result.importedName=String(c.importedName||c.name).slice(0,4000);result.overrides=Object.fromEntries(editableFields.filter(k=>c.overrides?.[k]===true).map(k=>[k,true]));if(c.importedFields)result.importedFields=Object.fromEntries(editableFields.map(k=>[k,String(c.importedFields[k]||'')]));result.photo=typeof c.photo==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(c.photo)?c.photo:undefined;return result})};decks.unshift(d);activeId=d.id;await persist(d);session=null;view='roster';render();toast('Your roster is back.')}catch(e){toast(e.message)}finally{$('#json-input').value=''}}
$('#pdf-input').onchange=e=>{const file=e.target.files[0];e.target.value='';importPDF(file)};$('#json-input').onchange=e=>restore(e.target.files[0]);
document.addEventListener('keydown',e=>{if($('#editor').open||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement?.tagName)||busy)return;if(view==='study'&&session&&session.index<session.ids.length){if(e.code==='Space'){e.preventDefault();action('flip')}if(e.key==='1')action('learning');if(e.key==='2')action('known');if(e.key==='ArrowRight')action('skip');if(e.key==='ArrowLeft')action('previous')}else if(view==='quiz'&&quizFormat==='choice'&&session&&!session.answered&&/^[1-4]$/.test(e.key)){const id=session.options[Number(e.key)-1];if(id)answer(id)}});
render();initDB().catch(()=>toast('Browser storage is unavailable. You can still import and export decks.'));
